--- Source/PixelArena/ArenaGameMode.h ---
#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// UPROPERTY so GC keeps it alive; a raw pointer here was collected
	// mid-match and crashed AddPoints in packaged builds (shipping log, frame 3684).
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "UArenaScoreTracker was stored in AArenaGameMode as a raw non-UPROPERTY pointer (ScoreTracker = NewObject<UArenaScoreTracker>(this)), so the garbage collector was free to collect it. The shipping log shows a GC pass purging 412 objects at frame 3684 and the crash right after: 'Unhandled Exception: EXCEPTION_ACCESS_VIOLATION reading address 0xffffffffffffffff' in UArenaScoreTracker::AddPoints (ArenaScoreTracker.cpp:18) called from AArenaGameMode::OnGoalScored (ArenaGameMode.cpp:38). The editor rarely GCs mid-match the same way, so it only crashed in the packaged build. Fix: changed the field to UPROPERTY() TObjectPtr<UArenaScoreTracker> in Source/PixelArena/ArenaGameMode.h so GC roots it.",
  "no_colors_cause": "The palette asset /Game/Data/Palettes/DA_Primary was never cooked into the package: Config/DefaultGame.ini had bCookAll=False and only /Game/Data/Effects was listed in DirectoriesToAlwaysCook, so /Game/Data/Palettes was excluded. The shipping log confirms it: \"LogStreaming: Error: Couldn't find file for package /Game/Data/Palettes/DA_Primary requested by async loading code\" and \"LogArena: Warning: Palette is null, using fallback gray\". It worked in the editor because the editor reads assets directly from the Content folder. Fix: added +DirectoriesToAlwaysCook=(Path=\"/Game/Data/Palettes\") to Config/DefaultGame.ini."
}
